const list = document.getElementById("fruits");
const input = document.getElementById("name");
let nextId = 3;

document.getElementById("add").addEventListener("click", () => {
  const text = input.value.trim();
  if (!text) return;
  const li = document.createElement("li");
  li.textContent = text;              // safe: no HTML parsing
  li.dataset.id = nextId++;
  list.append(li);
  input.value = "";
});
list.addEventListener("click", (e) => {
  if (e.target.matches("li")) e.target.remove();     // click an item to delete it
});
document.getElementById("style").addEventListener("click", () => {
  list.firstElementChild?.classList.toggle("hot");
});

