examples.js:
const log = document.getElementById("log");
let useCapture = false, stopAtInner = false;

function handler(e) {
  const li = document.createElement("li");
  li.textContent = `${e.currentTarget.id} (target: ${e.target.id})`;
  log.append(li);
  if (stopAtInner && e.currentTarget.id === "inner") e.stopPropagation();
}
function attach() {
  ["outer", "middle", "inner"].forEach((id) => {
    const el = document.getElementById(id);
    el.removeEventListener("click", handler, true);
    el.removeEventListener("click", handler, false);
    el.addEventListener("click", handler, useCapture);
  });
}
attach();
document.getElementById("capture").addEventListener("change", (e) => {
  useCapture = e.target.checked; attach(); log.innerHTML = "";
});
document.getElementById("stop").addEventListener("change", (e) => {
  stopAtInner = e.target.checked; log.innerHTML = "";
});

