examples.js:
const scroller = document.getElementById("scroller");
const statusEl = document.getElementById("status");

const io = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (entry.isIntersecting) {
      entry.target.classList.add("visible");
      statusEl.textContent = entry.target.textContent + " is visible (" + Math.round(entry.intersectionRatio * 100) + "%)";
    }
  });
}, { root: scroller, threshold: 0.5 });
document.querySelectorAll(".card").forEach((c) => io.observe(c));

const mlog = document.getElementById("mlog");
const mo = new MutationObserver((records) => {
  records.forEach((r) => (mlog.textContent += `${r.type}: +${r.addedNodes.length} node(s)\n`));
});
mo.observe(scroller, { childList: true });
document.getElementById("add").addEventListener("click", () => {
  const d = document.createElement("div");
  d.className = "card visible";
  d.textContent = "Dynamic card";
  scroller.append(d);
});

