examples.js:
const KEY = "todos-demo";
let todos = [];
try { todos = JSON.parse(localStorage.getItem(KEY)) || []; } catch { todos = []; }

const list = document.getElementById("list");
const count = document.getElementById("count");

function save() {
  try { localStorage.setItem(KEY, JSON.stringify(todos)); } catch {}
}
function render() {
  list.innerHTML = "";
  todos.forEach((t) => {
    const li = document.createElement("li");
    li.dataset.id = t.id;
    li.className = t.done ? "done" : "";
    const span = document.createElement("span");
    span.textContent = t.text;
    span.dataset.action = "toggle";
    const del = document.createElement("button");
    del.textContent = "x";
    del.dataset.action = "delete";
    li.append(span, del);
    list.append(li);
  });
  count.textContent = todos.filter((t) => !t.done).length + " left";
}
document.getElementById("form").addEventListener("submit", (e) => {
  e.preventDefault();
  const input = document.getElementById("text");
  const text = input.value.trim();
  if (!text) return;
  todos.push({ id: Date.now(), text, done: false });
  input.value = "";
  save(); render();
});
list.addEventListener("click", (e) => {
  const action = e.target.dataset.action;
  const id = Number(e.target.closest("li")?.dataset.id);
  if (action === "toggle") todos = todos.map((t) => (t.id === id ? { ...t, done: !t.done } : t));
  if (action === "delete") todos = todos.filter((t) => t.id !== id);
  if (action) { save(); render(); }
});
render();
